let lang='en';
try{const s=localStorage.getItem('aaiap-lang');if(LANGS.includes(s))lang=s;else if(/^ru\b/i.test(navigator.language||''))lang='ru';else if(/^tg\b/i.test(navigator.language||''))lang='tg'}catch{}
const listeners=new Set();
export const getLang=()=>lang;
export const locale=()=>LOCALE[lang];
export const sortLocale=()=>lang==='en'?'en':'ru';
export function t(key,params={}){
 const row=D[key];if(!row)return key;
 let s=row[IDX[lang]]??row[0];
 for(const [k,v] of Object.entries(params))s=s.replaceAll(`{${k}}`,esc(v));
 return s;
}
// Plain text (no markup) for textContent / attributes / toasts.
export const tt=(key,params)=>t(key,params).replace(/<sub>(.*?)<\/sub>/g,(_,d)=>d.replace(/\d/g,c=>'₀₁₂₃₄₅₆₇₈₉'[c])).replace(/<[^>]+>/g,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");
// Pick from a {en,ru,tg} object.
export const pick=o=>o?.[lang]??o?.en??'';
export const serverError=msg=>D['srv.'+msg]?tt('srv.'+msg):msg;
export function setLang(next){
 if(!LANGS.includes(next)||next===lang)return;
 lang=next;try{localStorage.setItem('aaiap-lang',lang)}catch{}
 applyStatic();listeners.forEach(fn=>fn(lang));
}
export const onLang=fn=>{listeners.add(fn);return()=>listeners.delete(fn)};
// Static markup in index.html: data-i18n="key" (html), data-i18n-attr="aria-label:key;title:key2"
export function applyStatic(root=document){
 document.documentElement.lang=lang==='tg'?'tg':lang;
 root.querySelectorAll('[data-i18n]').forEach(el=>{el.innerHTML=t(el.dataset.i18n)});
 root.querySelectorAll('[data-i18n-attr]').forEach(el=>{for(const pair of el.dataset.i18nAttr.split(';')){const [a,k]=pair.split(':');if(a&&k)el.setAttribute(a.trim(),tt(k.trim()))}});
 document.title=lang==='ru'?'AgroSupport (AAIAP) — Агроплатформа':lang==='tg'?'AgroSupport (AAIAP) — Платформаи кишоварзӣ':'AgroSupport (AAIAP) — Agronomic platform';
 document.querySelectorAll('[data-lang-btn]').forEach(b=>{const on=b.dataset.langBtn===lang;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});
}
// Theme (dark by default; follows the OS only when nothing has been chosen)
export function getTheme(){return document.documentElement.dataset.theme||'dark'}
export function setTheme(v){document.documentElement.dataset.theme=v;try{localStorage.setItem('aaiap-theme',v)}catch{};document.querySelector('meta[name=theme-color]')?.setAttribute('content',v==='dark'?'#002626':'#E0FFC2');window.dispatchEvent(new CustomEvent('themechange',{detail:v}))}
export function initTheme(){let v='dark';try{const s=localStorage.getItem('aaiap-theme');if(s==='light'||s==='dark')v=s;else if(matchMedia('(prefers-color-scheme: light)').matches)v='light'}catch{}setTheme(v)}
// Number formatting follows the active language (1 234,5 in RU/TJ, 1,234.5 in EN)
export const fmt=(n,max=2,min=0)=>n===null||n===undefined||n===''||!Number.isFinite(Number(n))?'—':new Intl.NumberFormat(LOCALE[lang],{maximumFractionDigits:max,minimumFractionDigits:min}).format(n);
